@import "tailwindcss";
@import "@fontsource-variable/geist";
@import "@fontsource/instrument-serif/400.css";
@import "@fontsource/instrument-serif/400-italic.css";

@source "./**/*.{ts,tsx}";

/* ---------------------------------------------------------------------------
   Design tokens.

   The palette is sampled from the six campaign renders: a dusk sky that runs
   lilac into coral, warm sunlit rock, deep moss, and the glowing white light
   that appears in every frame. That light is the brand motif and it is what
   the ember ramp below is for.
--------------------------------------------------------------------------- */
@theme {
  --font-sans: "Geist Variable", ui-sans-serif, system-ui, sans-serif;
  --font-display: "Instrument Serif", Georgia, "Times New Roman", serif;

  /* Surfaces, deepest to lightest. */
  --color-ink: #0a0710;
  --color-ink-2: #100b16;
  --color-ink-3: #17101f;
  --color-line: #251b30;
  --color-line-2: #33253f;

  /* Text. All three clear AA on --color-ink. */
  --color-cream: #f6f0f5;
  --color-mist: #c4b7ce;
  --color-haze: #9487a0;

  /* Ember: the sunset and the glow. Carries the original orange forward. */
  --color-ember-300: #ffc79a;
  --color-ember-400: #ff9a5c;
  --color-ember-500: #ff6b35;
  --color-ember-600: #e8501f;

  /* Dusk: the lilac half of the sky. */
  --color-dusk-300: #dcc9ef;
  --color-dusk-400: #b79bd6;
  --color-dusk-500: #8b6fae;

  --color-glow: #fff3e2;
  --color-moss: #7ea86f;

  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
}

:root {
  font-family: var(--font-sans);
  color: var(--color-cream);
  background: var(--color-ink);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  color-scheme: dark;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  /* Keep anchored sections clear of the fixed header. */
  scroll-padding-top: 5.5rem;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background: var(--color-ink);
  /* Never allow a stray full-bleed child to create a sideways scrollbar. */
  overflow-x: hidden;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

::selection {
  background: var(--color-ember-500);
  color: #fff;
}

:focus-visible {
  outline: 2px solid var(--color-ember-400);
  outline-offset: 3px;
  border-radius: 4px;
}

/* --------------------------------------------------------------------------
   Page shell
-------------------------------------------------------------------------- */
.landing-page {
  position: relative;
  background: var(--color-ink);
  color: var(--color-cream);
}

/* Film grain over the whole page. Keeps the renders from looking too clean. */
.landing-page::after {
  position: fixed;
  z-index: 60;
  inset: 0;
  pointer-events: none;
  content: "";
  opacity: 0.035;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E");
  background-repeat: repeat;
  background-size: 256px 256px;
}

/* --------------------------------------------------------------------------
   Typography helpers
-------------------------------------------------------------------------- */
.font-display {
  font-family: var(--font-display);
  font-weight: 400;
  letter-spacing: -0.015em;
}

/* Optical fix: Instrument Serif sits high and loose at display sizes. */
.display-tight {
  line-height: 0.95;
  letter-spacing: -0.025em;
}

.text-balance {
  text-wrap: balance;
}

.text-pretty {
  text-wrap: pretty;
}

.eyebrow {
  font-size: 0.6875rem;
  font-weight: 500;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

/* Ember gradient text, used sparingly on key promise words. */
.text-ember-gradient {
  background: linear-gradient(
    100deg,
    var(--color-ember-300) 0%,
    var(--color-ember-400) 45%,
    var(--color-dusk-400) 100%
  );
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

/* --------------------------------------------------------------------------
   Scroll reveal.

   Elements opt in with data-reveal. The observer in use-reveal.ts adds .is-in.
   Staggering is done with --reveal-delay so no JS runs per frame.
-------------------------------------------------------------------------- */
[data-reveal] {
  opacity: 0;
  transform: translate3d(0, 26px, 0);
  transition:
    opacity 0.9s var(--ease-out-expo),
    transform 0.9s var(--ease-out-expo);
  transition-delay: var(--reveal-delay, 0ms);
  will-change: opacity, transform;
}

[data-reveal="fade"] {
  transform: none;
}

[data-reveal="scale"] {
  transform: scale(1.04);
}

[data-reveal].is-in {
  opacity: 1;
  transform: none;
  will-change: auto;
}

/* --------------------------------------------------------------------------
   Motion
-------------------------------------------------------------------------- */
@keyframes drift {
  0% {
    transform: scale(1.06) translate3d(0, 0, 0);
  }
  100% {
    transform: scale(1.14) translate3d(0, -1.5%, 0);
  }
}

/* Very slow push on full-bleed campaign frames. */
.animate-drift {
  animation: drift 28s ease-in-out infinite alternate;
}

@keyframes breathe {
  0%,
  100% {
    opacity: 0.5;
    transform: scale(1);
  }
  50% {
    opacity: 0.85;
    transform: scale(1.06);
  }
}

.animate-breathe {
  animation: breathe 5s ease-in-out infinite;
}

@keyframes marquee {
  from {
    transform: translate3d(0, 0, 0);
  }
  to {
    transform: translate3d(-50%, 0, 0);
  }
}

.animate-marquee {
  animation: marquee 44s linear infinite;
}

@keyframes caret {
  0%,
  49% {
    opacity: 1;
  }
  50%,
  100% {
    opacity: 0;
  }
}

.animate-caret {
  animation: caret 1s step-end infinite;
}

@keyframes sweep {
  from {
    transform: translate3d(-120%, 0, 0);
  }
  to {
    transform: translate3d(320%, 0, 0);
  }
}

/* Light travelling across a rule, echoing the portal glow. */
.animate-sweep {
  animation: sweep 4.5s ease-in-out infinite;
}

@keyframes rise {
  from {
    opacity: 0;
    transform: translate3d(0, 10px, 0);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.animate-rise {
  animation: rise 0.5s var(--ease-out-expo) both;
}

/* --------------------------------------------------------------------------
   Reduced motion.

   Everything decorative stops. Reveals resolve to their final state so no
   content is left invisible, and the accordion still opens and closes.
-------------------------------------------------------------------------- */
@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    animation-delay: 0ms !important;
    transition-duration: 0.001ms !important;
    /* Staggered reveals must not leave content invisible while a delay runs. */
    transition-delay: 0ms !important;
    scroll-behavior: auto !important;
  }

  [data-reveal] {
    opacity: 1 !important;
    transform: none !important;
  }
}

