const page = await browser.getPage("main");
const errors = [];
page.on("console", (m) => { if (m.type() === "error") errors.push(m.text()); });
page.on("pageerror", (e) => errors.push("PAGEERROR: " + String(e)));

await page.setViewportSize({ width: 1440, height: 900 });
await page.goto("http://127.0.0.1:9221/", { waitUntil: "networkidle" });
await page.waitForTimeout(2500);

const info = await page.evaluate(() => ({
  title: document.title,
  h1: Array.from(document.querySelectorAll("h1")).map(e => e.textContent.trim()),
  docW: document.documentElement.scrollWidth,
  innerW: window.innerWidth,
  scrollH: document.documentElement.scrollHeight,
}));
console.log(JSON.stringify({ ...info, errors }, null, 2));

const buf = await page.screenshot();
console.log(await saveScreenshot(buf, "hero-desktop.png"));
EOF

dev-browser --headless --timeout 60 <<'EOF'
const page = await browser.getPage("main");
const over = await page.evaluate(() => {
  const limit = document.documentElement.clientWidth;
  const out = [];
  document.querySelectorAll("*").forEach((el) => {
    const r = el.getBoundingClientRect();
    if (r.right > limit + 1 || r.left < -1) {
      out.push({
        tag: el.tagName.toLowerCase(),
        cls: (el.className && el.className.baseVal !== undefined ? el.className.baseVal : String(el.className || "")).slice(0, 110),
        left: Math.round(r.left), right: Math.round(r.right), w: Math.round(r.width),
      });
    }
  });
  return { clientWidth: limit, count: out.length, items: out.slice(0, 14) };
});
console.log(JSON.stringify(over, null, 2));
EOF

