const page = await browser.getPage("opus5-verify");
const res = await page.evaluate(() => {
  const limit = document.documentElement.clientWidth;
  const clipped = (el) => {
    let n = el.parentElement;
    while (n) {
      const s = getComputedStyle(n);
      if (s.overflowX !== "visible") return n;
      n = n.parentElement;
    }
    return null;
  };
  const out = [];
  document.querySelectorAll("*").forEach((el) => {
    const r = el.getBoundingClientRect();
    if (r.width === 0) return;
    if (r.right > limit + 1 || r.left < -1) {
      const c = clipped(el);
      if (!c || c === document.body || c === document.documentElement) {
        out.push({
          tag: el.tagName.toLowerCase(),
          cls: String(el.className || "").slice(0, 110),
          left: Math.round(r.left),
          right: Math.round(r.right),
          clipper: c ? c.tagName.toLowerCase() : "none",
        });
      }
    }
  });
  // also: can the page actually scroll sideways?
  window.scrollTo(400, 0);
  const scrolledX = window.scrollX;
  window.scrollTo(0, 0);
  return { limit, scrollWidth: document.documentElement.scrollWidth, scrolledX, unclipped: out };
});
console.log(JSON.stringify(res, null, 2));
EOF

