for (let y = 0; y < h; y += 700) {
  await page.evaluate((v) => window.scrollTo(0, v), y);
  await page.waitForTimeout(160);
}
await page.evaluate(() => window.scrollTo(0, 0));
await page.waitForTimeout(900);

const res = await page.evaluate(() => {
  const limit = document.documentElement.clientWidth;
  const bad = [];
  document.querySelectorAll("*").forEach((el) => {
    const r = el.getBoundingClientRect();
    if (r.width === 0 || r.right <= limit + 1) return;
    let n = el.parentElement, clipped = false;
    while (n) { if (getComputedStyle(n).overflowX !== "visible") { clipped = true; break; } n = n.parentElement; }
    if (!clipped) bad.push(el.tagName + "." + String(el.className).slice(0, 60));
  });
  const hidden = [...document.querySelectorAll("[data-reveal]")]
    .filter((e) => getComputedStyle(e).opacity === "0").length;
  return {
    scrollWidth: document.documentElement.scrollWidth,
    clientWidth: limit,
    unclipped: bad,
    revealsStillHidden: hidden,
    totalReveals: document.querySelectorAll("[data-reveal]").length,
  };
});
console.log(JSON.stringify({ ...res, errors }, null, 2));
EOF

