    await chips.nth(i).click();
    await page.waitForTimeout(300);
    seen.add(await page.evaluate(() => Math.round(document.querySelector("[aria-live]").getBoundingClientRect().height)));
    await page.waitForFunction(() => document.querySelector("[aria-live]").getAttribute("aria-busy") === "false", { timeout: 20000 });
    await page.waitForTimeout(400);
    seen.add(await page.evaluate(() => Math.round(document.querySelector("[aria-live]").getBoundingClientRect().height)));
  }
  out[w] = { distinctHeights: [...seen] };
}
console.log(JSON.stringify(out, null, 2));
EOF

