    navDisplay: cs.display, navVisibility: cs.visibility,
    navRect: nav.getBoundingClientRect().toJSON(),
    linkRect: a.getBoundingClientRect().toJSON(),
    bodyOverflow: document.body.style.overflow,
  };
}), null, 2));
EOF

