dev-browser --headless --timeout 300 <<'EOF'
const page = await browser.newPage();
// Wait for the scroll to actually start, then for it to stop.
const settle = async () => {
  for (let i = 0; i < 20; i++) {                       // startup delay
    const a = await page.evaluate(() => window.scrollY);
    await page.waitForTimeout(150);
    if (await page.evaluate((v) => window.scrollY !== v, a)) break;
  }
  let prev = null;
  for (let i = 0; i < 60; i++) {                       // then settle
    const y = await page.evaluate(() => Math.round(window.scrollY));
    if (y === prev) return y;
    prev = y;
    await page.waitForTimeout(150);
  }
  return prev;
};
const out = {};
for (const [w, h] of [[1440, 900], [768, 900], [390, 844]]) {
  await page.setViewportSize({ width: w, height: h });
  await page.goto("http://127.0.0.1:9221/", { waitUntil: "networkidle" });
  await page.waitForTimeout(800);
  const res = {};
  for (const id of ["workflow", "promise", "ios", "pricing", "faq"]) {
    if (w < 768) {
      await page.locator('header button[aria-controls="mobile-nav"]').click();
      await page.waitForTimeout(400);
      await page.locator(`#mobile-nav a[href="#${id}"]`).click();
    } else {
      await page.locator(`header nav[aria-label="Primary"] a[href="#${id}"]`).click();
    }
    await settle();
    await page.waitForTimeout(600);
    res[id] = Math.round(await page.evaluate((i) => document.getElementById(i).getBoundingClientRect().top, id));
  }
  out[w] = res;
}
console.log(JSON.stringify(out, null, 2));
EOF

